"""Append distinct source criticism to era 10, preserving all pre-existing fields."""
import hashlib,json,re
from pathlib import Path
root=Path(__file__).resolve().parents[2]
addition={
'10-001':'''Начните с двух разных вопросов к декларации 1990 года: кто провозгласил полномочия и какие отношения с союзным центром документ предлагал изменить? Затем сопоставьте эти положения с устройством власти в Конституции 1993 года. Изменение нормы ещё не показывает, когда ведомство получило работников, имущество и возможность исполнять решения. Для этого потребуются датированные сведения о передаче полномочий и бюджетах. Исследование конституционного основания помогает поставить вопрос о преемственности, но его общий вывод нужно проверять на конкретном учреждении. Полезно составить таблицу из трёх столбцов: провозглашённое право, практический механизм и наблюдаемый результат. Если в одном столбце нет свидетельств, оставьте пробел и обозначьте, какой документ нужен для продолжения.''',
'10-002':'''Материалы МВФ описывают макроэкономическую стабилизацию: цены, бюджет и хозяйственные связи. Панельное обследование RLMS позволяет задать другой вопрос — как менялась жизнь одних и тех же домохозяйств. Эти уровни не противоречат друг другу, когда их показатели расходятся: общий выпуск и положение отдельной семьи измеряют разное. Сначала выберите результат, который хотите объяснить, например изменение реального дохода, затем перечислите возможные механизмы. Проверьте, не менялись ли одновременно состав семьи, занятость и доступ к выплатам. Регион с наиболее глубоким спадом мог иметь другую промышленную структуру ещё до реформ. Без такой исходной проверки различие последствий нельзя уверенно приписать только темпу приватизации или либерализации цен.''',
'10-003':'''У источников урока разные временные рамки. Исследование первых результатов освобождения цен не объясняет автоматически кризис 1998 года, а работа о занятости в 1991–1995 годах не описывает весь последующий переход. Для сравнения семейных потерь сначала зафиксируйте один набор товаров, затем выясните, мог ли он покупаться по указанным ценам и в каком количестве. Снижение официального дефицита не превращает любую новую цену в доступную. Отдельно рассматривайте заработную плату, пенсии, сбережения и доходы от самостоятельной деятельности. Когда источники используют разные исходные годы или группы населения, приведите показатели к сопоставимой основе либо прямо объясните, почему это невозможно. Такой порядок позволяет обсуждать выгоды и потери без подмены измеряемого результата.''',
'10-004':'''Текст Конституции 1993 года — первичный источник о закреплённых правилах. Научная статья о её основании предлагает объяснение того, почему эти правила сложились именно так; её тезис не равен самой норме закона. Выберите один спор между органами власти и восстановите путь решения: кто мог внести предложение, кто обладал правом остановить его, куда можно было обжаловать действие и было ли решение исполнено. Затем проверьте второй случай, когда участники имели другие политические предпочтения. Иначе успех одной стороны можно ошибочно принять за постоянное свойство всей системы. Гарантия права становится практически значимой через доступную процедуру защиты, независимое рассмотрение и исполнение результата; каждый из этих этапов требует отдельного свидетельства.''',
'10-005':'''Для начала составьте хронологию решений, используя дату подписания, объявления и фактического исполнения каждого акта. Эти моменты могут различаться. Указ № 1400 позволяет точно прочитать, что утверждал президент и какие действия предписывал, но позицию другого органа и тогдашние правовые ограничения нужно восстанавливать отдельно. Исследование последующего конституционного устройства помогает обсуждать последствия кризиса, однако не может заменить документы самих дней противостояния. При оценке насилия различайте приказ, его исполнение и установленную ответственность конкретных участников. Если источники дают разные сведения о жертвах, укажите состав учитываемых случаев, дату подсчёта и степень проверки. Расхождение не разрешается выбором удобного числа и не делает человеческие потери второстепенными.''',
'10-006':'''Указ о приватизационных чеках описывает предусмотренный механизм распределения прав, а исследование приватизации рассматривает изменения учреждений и интересы участников. Между получением чека и контролем над предприятием лежит цепочка решений: обмен, участие в покупке, распределение акций и возможность влиять на руководство. Проверьте каждое звено, прежде чем говорить, что все граждане стали собственниками на одинаковых условиях. Для оценки эффективности выберите период, сопоставьте исходное состояние предприятий и учтите доступ к кредиту и спрос на продукцию. Падение выпуска в момент сделки само по себе не доказывает её последствия: спад мог начаться раньше. Социальная справедливость также требует явного критерия — равенства стартовых прав, распределения дохода или защиты уязвимых групп.''',
'10-007':'''Совместное заявление августа 1998 года является источником о решениях властей и обещанном порядке действий. Обзор МВФ следующего года позволяет рассматривать последующую динамику, но его знание результата нельзя переносить на ожидания всех участников до кризиса. Постройте условный баланс банка: в какой валюте его доходы, кому и когда нужно платить, какие активы можно быстро продать. Затем по отдельности измените обменный курс и долю вкладчиков, требующих возврата денег. Это учебная модель, а не восстановленный баланс конкретного банка. Она показывает, какие документы нужны для реального объяснения: сроки долгов, валютная структура и доступ к рефинансированию. Название «дефолт» без уточнения обязательства скрывает различия между решениями государства и трудностями частных должников.''',
'10-008':'''Особенно внимательно выбирайте редакцию Конституции: современный сводный текст включает поправки и не может без проверки описывать устройство государства в начале 1990-х годов. Сопоставляя исследование отношений центра и региональных руководителей с законом, различайте формальное полномочие и неформальную зависимость. У назначения могут быть юридически несколько стадий, но решающее влияние сосредоточено на одной из них. Проверить это помогают последовательность выдвижения кандидатур, публичные основания решений и возможность отказа. Отдельно изучайте распределение денег и ответственности: региональный руководитель способен отвечать перед населением за услугу, не имея достаточного контроля над её финансированием. Такой разбор объясняет устройство управления через проверяемые действия, а не через одно общее название политической системы.''',
'10-009':'''Отчёт наблюдателей ОБСЕ о выборах 2018 года относится к конкретной кампании и процедурам наблюдения. Он позволяет обсуждать зарегистрированных кандидатов, условия агитации, подсчёт и доступность обжалования в пределах собранных материалов. Его нельзя превращать в готовую оценку любых выборов за несколько десятилетий или в опрос всех граждан. Исследование гибридных режимов предлагает понятия для сравнения, но применимость понятия проверяют по признакам, а не по авторитету названия. Разделите материал на условия до голосования, действия в день выборов и разбирательства после него. Затем укажите, какие сведения подтверждены документами, какие основаны на наблюдении, а какие являются объяснением автора. Это сохраняет различие между установленным эпизодом и выводом о системе.''',
'10-010':'''Обзор финансовой стабильности Банка России относится к обозначенному в нём периоду, а исследование неравенства — к своему набору данных и способу измерения. Их нельзя объединить в якобы единый снимок экономики на сегодняшнюю дату. Для каждого показателя запишите год, охват населения и единицу измерения. Средний доход, медианный доход и стоимость потребительской корзины отвечают на разные вопросы; региональные цены также меняют покупательную способность. Когда обсуждается рост выпуска, отдельно спросите, какое потребление и какие долгосрочные вложения стали возможны. Утверждение об общей пользе требует большего, чем отчёт о доходах одной отрасли. Для проверяемого вывода нужен указанный период сравнения и объяснение, почему выбранные группы или страны достаточно сопоставимы.''',
'10-011':'''Концепция внешней политики 2023 года является первичным свидетельством официально заявленных целей и языка власти. Она не доказывает ни неизбежность описанного конфликта, ни достоверность каждого утверждения о намерениях других государств. Исследование политики соседства предлагает объясняющую модель, а резолюция Генеральной Ассамблеи фиксирует международную оценку конкретного применения силы. Сопоставьте эти источники по вопросу, на который каждый способен ответить. Для мотива руководства полезны также последовательность решений и доступные альтернативы; для юридической оценки — применимая норма и установленное действие. Одно и то же заявление может быть важным источником о самоописании власти и слабым доказательством внешней угрозы. Укажите эту разницу до того, как строить причинное объяснение.''',
'10-012':'''Устав ООН закрепляет общие принципы отношений государств, а исследование соседства объясняет политические механизмы. Правовая равноправность стран совместима с сильным различием их населения, ресурсов и переговорных возможностей. Для выбранного спора выделите государства, правительства, предприятия и группы населения: их интересы не обязательно совпадают. Затем выясните, какая связь создаёт зависимость — транспортный маршрут, конкретный рынок, денежные переводы или поставки ресурса. Даже небольшой общий торговый оборот может скрывать критическую зависимость одной отрасли. Полезен вопрос об альтернативе: сколько стоит заменить поставщика и за какое время это возможно? Такой разбор помогает объяснить влияние хозяйственных отношений, не превращая соседнюю страну в пассивный объект решений более крупной державы.''',
'10-013':'''Материал Международного комитета Красного Креста помогает разбирать выбор целей и защиту гражданских лиц. Начните с установления того, что именно атаковали, какие сведения были доступны принимающему решение и какие меры предосторожности могли применяться. Сам факт гражданских жертв требует расследования, но полная юридическая оценка конкретного удара зависит от обстоятельств и применимых правил. Обратный вывод также неверен: объявление объекта «военным» одной стороной не доказывает правомерности нападения. Исследования конфликтов и международные резолюции выполняют разные задачи и должны использоваться с указанием их предмета. При недостатке данных честно разделите установленный вред, свидетельства о действиях и вопрос об индивидуальной ответственности. Пробел в доказательствах нельзя заполнять коллективной виной населения.''',
'10-014':'''Составьте несколько параллельных линий времени: изменения фактического контроля, официальные решения, боевые действия и международно-правовые оценки. Они связаны, но одна линия не заменяет остальные. Резолюции Генеральной Ассамблеи позволяют установить содержание международной позиции по территориальной целостности и агрессии, а доклад мониторинговой миссии — проверенные ею нарушения в определённом периоде. Исследование предыстории отвечает на иной вопрос о механизмах отношений соседей. При переходе от 2014 к 2022 году называйте конкретное действие и его дату, а не обобщённое «обострение». Не распространяйте документ о первых месяцах вторжения на последующие годы без дополнительного источника. Объяснение мотивов участников требует проверки и не отменяет ответственности за применение силы и вред гражданским лицам.''',
'10-015':'''Официальная страница Совета ЕС сообщает о правовых мерах, целях и предусмотренных исключениях со стороны вводящего санкции объединения. Исследовательская статья оценивает хозяйственные последствия с помощью модели и данных. Намерение изменить поведение, ограничение конкретной сделки и наблюдаемый экономический результат — три разных уровня анализа. Для отдельной меры уточните дату введения, круг товаров или лиц, способы исполнения и доступные пути замены. Затем спросите, какие другие изменения могли повлиять на выбранный результат, включая цены на сырьё и внутреннюю политику. Если модель оценивает длительный эффект, приведите её предпосылки и чувствительность расчёта. Не считайте рост одного сектора доказательством отсутствия потерь в других и не выдавайте заявленную цель санкций за уже достигнутую.''',
'10-016':'''Закон о науке показывает юридические определения и распределение обязанностей, доклад ЮНЕСКО — сравнительный взгляд на научные системы, а библиометрическое исследование — движение адресов авторов в определённой базе. Перед сравнением установите, что считается исследователем, публикацией и сменой страны. Учёные разных дисциплин публикуются с разной частотой, поэтому необработанное число статей не даёт равного измерения их активности. Миграция может расширять сотрудничество и одновременно ослаблять конкретный институт; для вывода нужны сведения о возвращениях, совместных проектах и подготовке молодых специалистов. Оценку научного результата также нельзя сводить к количеству публикаций. Сопоставляйте качество, воспроизводимость, инфраструктуру и возможность продолжать работу, ясно называя показатели, которые доступные источники не измеряют.''',
'10-017':'''Закон об образовании описывает права, уровни и обязанности участников, но его наличие не устанавливает одинакового доступа к хорошему обучению. Исследование участия России в Болонском процессе относится к конкретной политике и периоду, поэтому позднейшие изменения следует проверять отдельно. Для анализа реформы проследите переход от формального правила к учебному плану, работе преподавателя и результату ученика. Каждое звено может измениться иначе, чем предполагалось. Сравнивая экзаменационные баллы, учитывайте состав сдающих, содержание заданий и условия подготовки; рост среднего не всегда означает, что один и тот же круг учащихся научился большему. В культурной политике также различайте финансирование, административное решение и реальный выбор аудитории: один документ не описывает всего культурного опыта общества.''',
'10-018':'''В описании RLMS сначала изучите, кого опрашивали, как повторно находили участников и как учитывали неполученные ответы. Семья, прекратившая участие, может систематически отличаться от оставшихся, например по мобильности или доходам. Отсюда следует задача проверки смещения, а не основание отказаться от исследования. Затем сопоставьте денежные показатели с расходами, занятостью, жилищными условиями и оценкой собственного положения. Эти сведения дополняют друг друга, но субъективная неудовлетворённость не равна установленному падению реального дохода. Полезно проследить одну устойчиво определённую группу на протяжении нескольких волн и отдельно показать, как изменился состав населения. Это позволяет отличить перемены в жизни людей от перемен в составе тех, кто попал в очередное наблюдение.''',
'10-019':'''Конституция задаёт устройство федерации, а исследование бюджетных отношений позволяет спрашивать, кто получает доходы и кто обязан оплачивать услуги. Перед сравнением регионов разделите собственные поступления, перечисления из центра и целевое финансирование. Одинаковая итоговая сумма может сопровождаться разной свободой распоряжения. Затем выберите понятный результат: время до больницы, доступность школы или качество дороги. Расходы на человека лучше сопоставлять с этим результатом и особенностями территории, чем оценивать изолированно. Но связь расходов с качеством ещё не устанавливает причину: дополнительные средства могли направить как раз туда, где ситуация была тяжелее. Для объяснения нужны исходные условия, порядок распределения помощи и наблюдение за изменением результата после её получения.''',
'10-020':'''Отчёт Комиссии ООН, исследование Sciences Po и меморандум Human Rights Watch созданы в разное время и имеют разный предмет. Сначала установите, какой эпизод, место и период охватывает каждый материал, каким образом авторы собирали сведения и что могли проверить лично. Повторение одного свидетельства несколькими публикациями не превращает его в несколько независимых подтверждений. При этом ограничение доступа не обесценивает согласующиеся проверенные показания. Для конкретного случая отделите установленную гибель или разрушение от предположения о подразделении и приказе. Укажите, какая дополнительная информация нужна для связи события с командованием. Такой способ сохраняет внимание к жертвам и ответственности и не превращает преступления вооружённой группы в характеристику всех чеченцев или всех российских граждан.''',
'10-021':'''Демографический ежегодник даёт численность и структуру населения в определённых границах и по правилам официального учёта. Научные работы о смертности анализируют механизмы и могут применять другие сопоставления. Перед объединением рядов проверьте территориальный охват, возрастные группы и пересмотры оценок. Ожидаемая продолжительность жизни — расчётный показатель при текущих уровнях смертности, а не предсказание возраста смерти каждого новорождённого. На число рождений влияют и численность потенциальных родителей, и их поведение; на общую численность — также миграция. Поэтому для оценки отдельной меры поддержки нужны подходящая группа сравнения и длительный период наблюдения. Один удачный год ещё не показывает устойчивого изменения поколенческой рождаемости или устранения причин преждевременных смертей.''',
'10-022':'''Обзор МВФ и исследование OSW описывают российский кризис в связи с внешними финансовыми потрясениями, но для объяснения важно разделить каналы передачи. Условно проследите три цепочки: изменение экспортной выручки, затруднение получения кредита и падение ожиданий покупателей. В каждой цепочке назовите первый удар, уязвимого участника и решение, которое усилило либо смягчило последствия. Это схема анализа, а не утверждение одинаковой глубины всех механизмов. При оценке поддержки банков различайте предоставленную сумму, реально использованные средства и конечную стоимость для бюджета. Восстановление после помощи не доказывает её достаточности: часть изменения могла быть связана с внешней конъюнктурой. Для обоснованного вывода потребуются сроки вмешательства и сопоставимые данные до и после него.''',
'10-023':'''Сводная Конституция позволяет прочитать действующую редакцию, но для изучения поправок необходимо сопоставить прежнюю и новую формулировки. Отдельно восстановите процедуру внесения, рассмотрения и вступления изменений в силу. Заключение Венецианской комиссии является экспертной правовой оценкой с обозначенным предметом, а не решением российского суда и не измерением общественного мнения. Проверьте, какую часть изменения оно рассматривает и на какие нормы опирается. Затем разделите юридическую возможность вновь баллотироваться, решение воспользоваться ею и фактический исход выборов: это разные события. Политические последствия оцениваются по поведению учреждений и доступности конкуренции, а не выводятся автоматически из одной статьи. Указание временных границ защищает от переноса более поздних результатов на намерения всех участников 2020 года.''',
'10-024':'''Материал ВОЗ объясняет общий подход к избыточной смертности, а исследования России используют свои временные ряды, региональный охват и предположения о базовом уровне. Чтобы сравнить оценки, выпишите ожидаемое и наблюдаемое число смертей, период и поправки на структуру населения. Разность включает прямые и косвенные последствия, поэтому её нельзя автоматически назвать числом лабораторно подтверждённых смертей от инфекции. Региональная разница также может отражать возрастной состав и полноту регистрации, а не только работу местных властей. Проверяйте, сохраняется ли вывод при другой разумной базовой линии. Это особенно важно при оценке мер: совпадение введения ограничения с ростом смертности может означать, что его приняли в ответ на уже ухудшавшуюся ситуацию, а не что ограничение вызвало этот рост.''',
'10-025':'''Резолюция Генеральной Ассамблеи 68/262 фиксирует позицию о территориальной целостности Украины и отсутствии у голосования в Крыму силы, изменяющей статус территории. Научная статья разбирает правовые аргументы в более широком контексте международных отношений. Их следует читать как разные виды источников: документ о выраженной государствами позиции и авторский юридический анализ. Затем отделите сведения о воле жителей от вопроса о допустимой процедуре изменения границ. Даже достоверный опрос сам по себе не устанавливает правового титула государства на территорию. Исследование условий голосования требует данных о безопасности, свободе агитации и доступе наблюдателей. Реальное управление и признанный суверенитет описываются отдельно, чтобы картографическое обозначение фактического контроля не превращалось в скрытый юридический вывод.''',
'10-026':'''Текст Комплекса мер позволяет составить перечень обязательств, но не сообщает автоматически, насколько каждое из них было выполнено. Резолюция Совета Безопасности 2202 показывает международное одобрение соглашений и не является ежедневным отчётом с линии соприкосновения. Научное исследование разбирает политические противоречия и последовательность шагов; его выводы также требуют проверки по датированным материалам. Для одного пункта соглашения укажите требуемое действие, срок, участника и способ наблюдения. Затем отделите спор о толковании пункта от свидетельств о фактическом нарушении. Если независимый контроль отсутствовал, это ограничивает уверенность, но не позволяет считать любую официальную версию равно доказанной. Рассматривая причины неисполнения, различайте недостаток способности, отсутствие согласия и сознательное решение нарушить обязательство.''',
'10-027':'''Сводка мониторинговой миссии от 16 февраля 2026 года использует данные по 31 января 2026 года. Это две разные даты: выпуск документа не переносит его наблюдения автоматически на весь февраль. Для каждого числа уточняйте территорию, категорию жертв и условия подтверждения. Недоступные для проверки случаи могут оставаться вне учёта, поэтому установленный минимум нельзя превращать в итоговое число всех потерь. Резолюция об агрессии и отчёт о нарушениях выполняют разные задачи: первая фиксирует международную квалификацию действий государства, второй документирует определённые последствия и события. Ни один не подменяет индивидуальный уголовный процесс. Все выводы этого урока ограничены названными документами; события после последней использованной сводки здесь не представлены как проверенная актуальная хроника.''',
'10-028':'''Берклийский протокол помогает выстроить проверку цифрового материала: зафиксировать происхождение, сохранить доступную копию, установить время и место и описать цепочку рассуждения. Метод не превращает любой ролик с похожим зданием в окончательное доказательство. Исследование работы с открытыми источниками позволяет обсудить, какие действия воспроизводимы другим проверяющим, а какие зависят от недоступного предположения. Разделите наблюдение и вывод: «видна дымовая полоса» сообщает меньше, чем «установлена конкретная сторона, выпустившая ракету». Для второго утверждения нужны дополнительные связующие сведения. Дата загрузки не обязательно совпадает с датой съёмки; несколько перепечаток могут восходить к одному файлу. Убедительная проверка сохраняет неопределённость там, где материала недостаточно, и ясно объясняет, какое новое свидетельство способно изменить вывод.''',
}
assert len(addition)==28
snapshot=[]
checks=[]
for lid,extra in addition.items():
 p=root/f'src/content/lessons/{lid}.json';x=json.loads(p.read_text())
 assert x['id']==lid and x['status']=='written',(lid,'status')
 original=x['deep']['text']
 snapshot.append({'id':lid,'deep':dict(x['deep']),'status':x['status'],'sources':list(x['sources'])})
 before=json.loads(json.dumps(x));x['deep']['text']=original+'\n\n'+extra
 count=len(re.findall(r'\S+',x['deep']['text']))
 assert count>=100,(lid,count)
 difference=json.loads(json.dumps(x));difference['deep']['text']=original
 assert difference==before,(lid,'other field changed')
 checks.append({'id':lid,'wordsBefore':len(re.findall(r'\S+',original)),'wordsAfter':count,'prefixPreserved':x['deep']['text'].startswith(original+'\n\n'),'status':x['status'],'otherFieldsUnchanged':difference==before})
 with p.open('w') as f:json.dump(x,f,ensure_ascii=False,indent=2);f.write('\n')
folder=root/'tasks/001-russian-history-course'
for name,data in [('modern-deep-original.json',snapshot),('modern-deep-validation.json',checks)]:
 with (folder/name).open('x') as f:json.dump(data,f,ensure_ascii=False,indent=2);f.write('\n')
print('Expanded',len(checks),'deep texts; minimum',min(x['wordsAfter'] for x in checks),'words; all original prefixes and other fields preserved')
